use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let n = input["n"].as_u64().unwrap();
    let start = input["start"].as_u64().unwrap();
    let target = input["target"].as_u64().unwrap();
    let edges = input["edges"].as_array().unwrap();

    let mut distances = vec![std::i64::MAX; n];
    distances[start as usize] = 0;

    for edge in edges {
        let u = edge[0].as_u64().unwrap();
        let v = edge[1].as_u64().unwrap();
        let weight = edge[2].as_i64().unwrap();

        if distances[u as usize] != std::i64::MAX && distances[v as usize] == std::i64::MAX {
            distances[v as usize] = distances[u as usize] + weight;
        }
    }

    if distances[target as usize] == std::i64::MAX {
        serde_json::Value::Null
    } else {
        serde_json::Value::Number(distances[target as usize] as f64)
    }
}
